/**
 * @distilled.cloud/netbox — NetBox REST API SDK for Effect.
 *
 * `./services` is generated by `scripts/generate.ts` from the Smithy models
 * in `.generated-specs` (written by `scripts/convert.ts` from NetBox's
 * committed OpenAPI 3.0.3 document in the `spec-mirror-netbox` submodule
 * under `specs/`, split by the document's own `tags`). Everything else in
 * this folder is hand-written.
 *
 * One module per NetBox app — `dcim`, `ipam`, `circuits`, `virtualization`,
 * `tenancy`, `vpn`, `wireless`, `users`, `extras`, `core` — plus three
 * single-endpoint utility modules (`schema`, `status`,
 * `authentication_check`), the same split NetBox's own API reference uses.
 *
 * @example
 * ```ts
 * import * as Netbox from "@distilled.cloud/netbox";
 *
 * const prefixes = yield* Netbox.Services.ipam.ipamPrefixesList({});
 * ```
 */
export * from "./credentials.ts";
export * from "./errors.ts";
export * as T from "./traits.ts";
export {
  NetboxProtocol,
  type NetboxOpError,
  type NetboxOpContext,
} from "./protocol.ts";
export * as Retry from "./retry.ts";
export * as Services from "./services/index.ts";
